using GraphApi.Models.SGR.MenusBotones;namespace GraphApi.Services.SGR.MenusBotones{    /// <summary>    /// Define las operaciones de negocio y persistencia para MenusBotones.    /// </summary>    public interface IMenusBotonesService    {        /// <summary>        /// Obtiene la lista de MenusBotones con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadMenusBotones>> GetMenusBotones(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de MenusBotones con filtros opcionales.        /// </summary>        /// <param name="menuBotonID">Filtro opcional para MenuBotonID.</param>        /// <param name="menuID">Filtro opcional para MenuID.</param>        /// <param name="tituloMenu">Filtro opcional para TituloMenu.</param>        /// <param name="boton">Filtro opcional para Boton.</param>        /// <param name="accion">Filtro opcional para Accion.</param>        /// <param name="orden">Filtro opcional para Orden.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetMenusBotonesDynamic(            int? menuBotonID,            int? menuID,            string? tituloMenu,            string? boton,            string? accion,            int? orden,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo MenusBotone.        /// </summary>        /// <param name="objInput">Datos para crear el MenusBotone.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadMenusBotones> CreateMenusBotones(            clCreateMenusBotones objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un MenusBotone.        /// </summary>        /// <param name="objInput">Datos para actualizar el MenusBotone, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadMenusBotones?> UpdateMenusBotones(            clUpdateMenusBotones objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un MenusBotone por su ID.        /// </summary>        /// <param name="nMenusBotonesID">ID del MenusBotone a eliminar.</param>        Task<bool> DeleteMenusBotones(int nMenusBotonesID);    }}